CREATE VIEW airlinerra_game.airport_group2_section1_official_source_progress_v1
 WITH (security_invoker=true) AS
SELECT
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_game_profiles_v1) AS total_group2_airports,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_source_candidates_v1
  WHERE identity_field='served_city' AND source_kind<>'AIRLINESIM_THIRD_PARTY_SIMULATION') AS primary_served_city_candidates,
 (SELECT count(DISTINCT airport_key)::integer FROM airlinerra_game.airport_group2_section1_source_candidates_v1
  WHERE identity_field='served_city' AND source_kind<>'AIRLINESIM_THIRD_PARTY_SIMULATION') AS airports_with_primary_served_city_candidate,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_source_candidates_v1
  WHERE identity_field='elevation_reference' AND source_kind<>'AIRLINESIM_THIRD_PARTY_SIMULATION') AS published_elevation_candidates,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_source_candidates_v1
  WHERE source_kind='AIRLINESIM_THIRD_PARTY_SIMULATION') AS airlinesim_code_only_comparisons,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_identity_quality_v1
  WHERE source_municipality_missing AND served_city_primary_candidates=0) AS missing_locality_without_primary_candidate,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_identity_quality_v1
  WHERE source_municipality_missing AND served_city_primary_candidates>0) AS missing_locality_with_primary_candidate,
 (SELECT count(*)::integer FROM airlinerra_game.airport_group2_section1_source_candidates_v1
  WHERE independently_authority_verified) AS independently_approved_corrections,
 false AS section1_verified_complete,
 false AS commercial_flights_authorized;
REVOKE ALL ON airlinerra_game.airport_group2_section1_official_source_progress_v1
 FROM PUBLIC,anon,authenticated;
DO $verify$
BEGIN
 IF (SELECT count(*) FROM airlinerra_game.airport_group2_section1_source_candidates_v1)<>37
 OR (SELECT airports_with_primary_served_city_candidate
     FROM airlinerra_game.airport_group2_section1_official_source_progress_v1)<>24
 OR (SELECT published_elevation_candidates
     FROM airlinerra_game.airport_group2_section1_official_source_progress_v1)<>7
 OR (SELECT missing_locality_without_primary_candidate
     FROM airlinerra_game.airport_group2_section1_official_source_progress_v1)<>17
 OR (SELECT missing_locality_with_primary_candidate
     FROM airlinerra_game.airport_group2_section1_official_source_progress_v1)<>24
 OR (SELECT count(*) FROM airlinerra_game.airport_group2_review_evidence_events_v1)<>0
 OR (SELECT count(*) FROM airlinerra_game.approved_game_airports WHERE world_id=1)<>3141
 OR (SELECT count(*) FROM airlinerra_game.airport_group2_game_profiles_v1)<>1118
 THEN RAISE EXCEPTION 'SECTION1_SOURCED_LOCALITY_ELEVATION_ACCEPTANCE_FAILED'; END IF;
END $verify$;
